const b=$('Board');b.style.setProperty('--bb-n',size);b.innerHTML=board.map((c,i)=>'<button class="bb-cell '+(c?'filled':'')+'" style="'+(c?'--tile:'+c:'')+'" data-n="'+i+'" aria-label="Row '+(Math.floor(i/size)+1)+', column '+((i%size)+1)+'"></button>').join('');b.querySelectorAll('button').forEach(cell=>{cell.onclick=()=>{if(Date.now()-(window.bbLastDragAt||0)<260)return;if(selected>=0)tryPlace(selected,Number(cell.dataset.n)%size,Math.floor(Number(cell.dataset.n)/size))};cell.onpointerenter=()=>{if(selected>=0&&!drag)highlight(Number(cell.dataset.n)%size,Math.floor(Number(cell.dataset.n)/size))}});b.onpointerleave=()=>{if(!drag)clearPreview()};const hand=chosen();const el=$('Hand');el.innerHTML=hand.map((p,i)=>'<button data-i="'+i+'" aria-label="Piece '+(i+1)+(p?', '+p.cells.length+' blocks':' used')+'" class="bb-piece '+(i===selected?'active':'')+'" '+(!p||!playing?'disabled':'')+'>'+(p?'<span class="bb-shape">'+p.cells.map(([x,y])=>'<span style="grid-column:'+(x+1)+';grid-row:'+(y+1)+';--tile:'+p.color+'"></span>').join('')+'</span>':'<small>USED</small>')+'</button>').join('');el.querySelectorAll('button').forEach(btn=>{const p=hand[Number(btn.dataset.i)],shape=btn.querySelector('.bb-shape');if(p&&shape){shape.style.gridTemplateColumns='repeat('+(Math.max(...p.cells.map(c=>c[0]))+1)+',var(--tray-cell,14px))';shape.style.gridTemplateRows='repeat('+(Math.max(...p.cells.map(c=>c[1]))+1)+',var(--tray-cell,14px))';}btn.onpointerdown=e=>{if(e.button!==0&&e.pointerType==='mouse')return;let i=Number(btn.dataset.i),p=chosen()[i];if(!p||!playing||drag)return;e.preventDefault();drag={index:i,piece:p,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,active:false,startedAt:performance.now()};dragPointerType=e.pointerType||'mouse';btn.setPointerCapture?.(e.pointerId);};btn.onclick=e=>{e.preventDefault()}});countScore();$('Motion').textContent=reduced?'Motion: Reduced':'Motion: Full';$('Motion').setAttribute('aria-pressed',String(reduced));$('Best').textContent=best.to