function boardCoords(clientX,clientY,p){
 const b=$('Board'),r=b?.getBoundingClientRect(),first=b?.children?.[0]?.getBoundingClientRect(),next=b?.children?.[1]?.getBoundingClientRect();
 if(!r||!first||!p)return null;
 const step=next?next.left-first.left:first.width;
 const offsetY=dragPointerType==='touch'?Math.min(92,step*1.6):0;
 const pointY=clientY-offsetY;
 if(clientX<r.left||clientX>r.right||pointY<r.top||pointY>r.bottom)return null;
 const w=Math.max(...p.cells.map(c=>c[0]))+1,h=Math.max(...p.cells.map(c=>c[1]))+1;
 const x=Math.round((clientX-first.left-first.width/2)/step-(w-1)/2);
 const y=Math.round((pointY-first.top-first.height/2)/step-(h-1)/2);
 return {x,y};
}
function highlight(x,y,p=chosen()[selected]){clearPreview();if(!p)return;let ok=placeOK(p,x,y);p.cells.forEach(([dx,dy])=>{let i=(y+dy)*size+x+dx;if(x+dx>=0&&y+dy>=0&&x+dx<size&&y+dy<size&&i>=0&&i<size*size)$('Board').children[i]?.classList.add(ok?'ghost':'bad')});}
function clearPreview(){$('Board')?.querySelectorAll('.ghost,.bad').forEach(c=>c.classList.remove('ghost','bad'));}
function drawPreview(x,y,p){const at=boardCoords(x,y,p);if(at)highlight(at.x,at.y,p);else clearPreview();}
function makeGhost(p,x,y){removeGhost();let e=document.createElement('div');e.id='bbDragGhost';e.className='bb-drag-ghost';const width=Math.max(...p.cells.map(c=>c[0]))+1,height=Math.max(...p.cells.map(c=>c[1]))+1;e.innerHTML='<div class="bb-shape">'+p.cells.map(([cx,cy])=>'<span style="grid-column:'+(cx+1)+';grid-row:'+(cy+1)+';--tile:'+p.color+'"></span>').join('')+'</div>';e.dataset.w=width;e.dataset.h=height;document.body.appendChild(e);moveGhost(x,y);}
function moveGhost(x,y){
 const e=$('DragGhost'),p=drag?.piece,b=$('Board'),first=b?.children[0]?.getBoundingClientRect(),next=b?.children[1]?.getBoundingClientRect();if(!e||!p||!first)return;
 const step=next.left-first.left,w=Number(e.dataset.w),h=Number(e.dataset.h),at=boardCoords(x,y,p),offset=dragPointerType==='touch'?Math.min(92,step*1.6):0;
 e.style.left=(at?first.left+at.x*step:x-(w*step-(step-first.width))/2)+'px';
 e.style.top=(at?first.top+at.y*step:y-offset-(h*step-(step-first.height))/2)+'px';
 e.style.setProperty('--ghost-cell',first.width+'px');e.firstElementChild.style.cssText='grid-template-columns:repeat('+w+','+first.width+'px);grid-template-rows:repeat('+h+','+first.height+'px);gap:'+(step-first.width)+'px';drawPreview(x,y,p);
}
function returnGhost(index){const ghost=$('DragGhost'),target=$('Hand')?.children[index];clearPreview();if(!ghost||!target||reduced){removeGhost();return;}ghost.id='';const a=ghost.getBoundingClientRect(),b=target.getBoundingClientRect();ghost.animate([{transform:'translate(0,0) scale(1)',opacity:.8},{transform:'translate('+(b.left+b.width/2-a.left-a.width/2)+'px,'+(b.top+b.height/2-a.top-a.height/2)+'px) scale(.42)',opacity:0}],{duration:230,easing:'cubic-bezier(.2,.8,.2,1)'}).finished.then(()=>ghost.remove(),()=>ghost.remove());}
function removeGhost(){$('DragGhost')?.remove();clearPreview();}
